123	void gpu_pipeline_executor::manager_loop()
124	{
125	  telemetry::TaskManagerLoopThreadHandleWrapper manager_thread_telemetry{
126	    *_telemetry_context,
127	    std::format("gpu-{}-exec-manager", _memory_space->get_device_id()),
128	    _telemetry_context->manager_thread_group_id(_memory_space->get_device_id())};
129	
130	  rmm::cuda_set_device_raii set_device_guard(rmm::cuda_device_id{_memory_space->get_device_id()});
131	  sirius::util::enable_log_on_default_stream();
132	  while (_running.load()) {
133	    auto slot = _bounded_pool->reserve();  // block till a thread is available
134	    if (!slot) {
135	      SIRIUS_LOG_INFO("GPU Pipeline Executor: pool interrupted, stopping manager loop");
136	      break;
137	    }
138	    // Pull-signal backpressure: now that we hold a reserved thread slot, tell the
139	    // task_scheduler this device is ready for work. The scheduler will only move
140	    // a task out of its downgrade-visible queue into our _task_queue when a
141	    // ready signal has been received from us — preventing tasks from piling
142	    // up here where the downgrade executor can't see them.
143	    auto ready       = std::make_unique<task_request>();
144	    ready->kind      = task_request_kind::device_ready;
145	    ready->device_id = _memory_space->get_device_id();
146	
147	    std::unique_ptr<parallel::itask> pipeline_task = nullptr;
148	    {
149	      if (!_task_request_publisher.send(std::move(ready))) {
150	        SIRIUS_LOG_INFO(
151	          "GPU Pipeline Executor: task_request channel closed, stopping manager loop");
152	        break;
153	      }
154	      pipeline_task = _task_queue.pop();  // block till a task is available
155	    }
156	    if (!pipeline_task) {
157	      SIRIUS_LOG_INFO("GPU Pipeline Executor: task queue interrupted, stopping manager loop");
158	      break;
159	    }
160	    auto* gpu_task = cast_to_gpu_pipeline_task(pipeline_task.get());
161	    if (!gpu_task) {
162	      SIRIUS_LOG_ERROR("GPU Pipeline Executor: Failed to cast pipeline task to gpu_pipeline_task");
163	      if (_completion_handler) {
164	        _completion_handler->report_error(
165	          "GPU Pipeline Executor: Failed to cast pipeline task to gpu_pipeline_task");
166	      }
167	      break;
168	    }
169	    // Once the query has failed, nothing queued here can matter any more: drop the task instead
170	    // of paying a blocking make_reservation() and a dispatch for it. Safe for the next query
171	    // because task_scheduler::prepare_for_query installs a fresh completion handler on every
172	    // executor before it schedules anything. Dropping the unique_ptr destroys the task and
173	    // releases the reserved slot, exactly like drain_leftover_tasks() does.
174	    if (_completion_handler && _completion_handler->has_error()) {
175	      SIRIUS_LOG_DEBUG(
176	        "GPU Pipeline Executor: dropping task {} for pipeline {}: the query already failed",
177	        gpu_task->get_task_id(),
178	        gpu_task->get_pipeline_id());
179	      continue;
180	    }
181	    // Pass this executor's memory space so cross-space inputs (host/disk tiers and GPU data on
182	    // another device, which prepare clones into this space) are counted in the reservation.
183	    auto reservation_info = gpu_task->get_estimated_reservation_size_info(_memory_space);
184	    auto bytes_needs      = reservation_info.reservation_size;
185	    gpu_task->telemetry_handle().reserving({
186	      .instance_name              = "",
187	      .requested_bytes            = reservation_info.reservation_size,
188	      .input_basis                = reservation_info.input_basis,
189	      .peak_estimate              = reservation_info.peak_memory_estimate,
190	      .bytes_to_materialize       = reservation_info.bytes_to_materialize_input,
191	      .manager_thread_resource_id = manager_thread_telemetry.handle->uuid(),
192	    });
193	    // Clamp the reservation request to what this memory space can actually
194	    // grant (its reservation limit). The history-based estimate can balloon far
195	    // past capacity — a small input that once drove a near-cap peak yields a
196	    // huge peak/estimate ratio that extrapolates to multi-GiB estimates on a
197	    // GiB-budget GPU. make_reservation() then returns only a partial reservation
198	    // and the downgrade predicate below (which must reserve the *full*
199	    // bytes_needs) can never succeed, so the task livelocks through the
200	    // OOM-reschedule loop until the retry cap trips and the query fails. Capping
201	    // at get_max_memory() keeps both the reservation and the downgrade target
202	    // achievable; any per-batch overflow during execution is still handled by
203	    // the OOM-reschedule + tiering path. (Telemetry above intentionally reports
204	    // the pre-clamp estimate so the estimator can still be analyzed.)
205	    if (auto const space_max = _memory_space->get_max_memory();
206	        space_max > 0 && bytes_needs > space_max) {
207	      SIRIUS_LOG_DEBUG(
208	        "GPU Pipeline Executor: clamping reservation request {} -> {} bytes (space max) for "
209	        "pipeline {} task {}",
210	        bytes_needs,
211	        space_max,
212	        gpu_task->get_pipeline_id(),
213	        gpu_task->get_task_id());
214	      bytes_needs = space_max;
215	    }
216	    SIRIUS_LOG_TRACE(
217	      "[GPU:{}] GPU Pipeline Executor: Acquiring memory reservation for pipeline {} of {} bytes "
218	      "for task {}. Memory available: {}, total reserved: {}, max: {}",
219	      _memory_space->get_device_id(),
220	      gpu_task->get_pipeline_id(),
221	      bytes_needs,
222	      gpu_task->get_task_id(),
223	      _memory_space->get_available_memory(),
224	      _memory_space->get_total_reserved_memory(),
225	      _memory_space->get_max_memory());
226	    // Snapshot the completion epoch before the (possibly blocking) reservation: the futility rule
227	    // compares it with the epoch after this attempt's OOM to learn whether anything finished in
228	    // between. `freed` / `downgrade_requested` are recorded on the task with the grant below.
229	    auto const epoch_at_gate = _progress->completed_epoch.load(std::memory_order_acquire);
230	    size_t freed             = 0;
231	    bool downgrade_requested = false;
232	    auto reservation         = _memory_space->make_reservation(bytes_needs);
233	    if (!reservation) {
234	      SIRIUS_LOG_ERROR("GPU Pipeline Executor: Failed to acquire memory reservation for task {}",
235	                       gpu_task->get_task_id());
236	      if (_completion_handler) {
237	        _completion_handler->report_error(
238	          "GPU Pipeline Executor: Failed to acquire memory reservation for task " +
239	          std::to_string(gpu_task->get_task_id()));
240	      }
241	      break;
242	    } else if (reservation->size() < bytes_needs && _downgrade_executor) {
243	      size_t shortfall    = bytes_needs - reservation->size();
244	      size_t partial_size = reservation->size();
245	
246	      gpu_task->telemetry_handle().downgrading({
247	        .instance_name              = "",
248	        .shortfall_bytes            = shortfall,
249	        .partial_bytes              = partial_size,
250	        .manager_thread_resource_id = manager_thread_telemetry.handle->uuid(),
251	      });
252	
253	      SIRIUS_LOG_DEBUG(
254	        "GPU Pipeline Executor: requested reservation size {} but only got {} bytes, reservation "
255	        "shortfall {} bytes for pipeline {} "
256	        "task {}, requesting predicate-based downgrade",
257	        bytes_needs,
258	        partial_size,
259	        shortfall,
260	        gpu_task->get_pipeline_id(),
261	        gpu_task->get_task_id());
262	
263	      reservation.reset();  // release partial reservation before downgrade
264	      downgrade_requested = true;
265	
266	      std::unique_ptr<cucascade::memory::reservation> new_reservation;
267	      auto* mem_space = _memory_space;
268	      std::mutex reservation_mutex;
269	      try {
270	        freed =
271	          _downgrade_executor
272	            ->request_downgrade([mem_space, bytes_needs, &new_reservation, &reservation_mutex]() {
273	              std::lock_guard<std::mutex> lock(reservation_mutex);
274	              if (new_reservation) { return true; }
275	              auto res = mem_space->make_reservation_or_null(bytes_needs);
276	              if (res && res->size() >= bytes_needs) { new_reservation = std::move(res); }
277	              return new_reservation != nullptr;
278	            })
279	            .get();
280	      } catch (const std::exception& e) {
281	        SIRIUS_LOG_INFO("GPU Pipeline Executor: downgrade request cancelled for task {}: {}",
282	                        gpu_task->get_task_id(),
283	                        e.what());
284	        break;
285	      }
286	
287	      if (new_reservation) {
288	        reservation = std::move(new_reservation);
289	      } else {
290	        // Predicate never succeeded — try one final reservation attempt
291	        reservation = _memory_space->make_reservation(bytes_needs);
292	      }
293	
294	      if (!reservation) {
295	        SIRIUS_LOG_ERROR(
296	          "GPU Pipeline Executor: Failed to acquire memory reservation after "
297	          "downgrade for task {} (freed {} bytes)",
298	          gpu_task->get_task_id(),
299	          freed);
300	        if (_completion_handler) {
301	          _completion_handler->report_error(
302	            "GPU Pipeline Executor: Failed to acquire memory reservation "
303	            "after downgrade for task " +
304	            std::to_string(gpu_task->get_task_id()));
305	        }
306	        break;
307	      }
308	      if (reservation->size() < bytes_needs) {
