   266	void task_scheduler::drain_after_error()
   267	{
   268	  SIRIUS_LOG_INFO("task_scheduler: draining after error");
   269	  // Teardown ordering is load-bearing. The scan/gpu executor drains below run
   270	  // in-flight tasks to completion, and a completing task schedules its
   271	  // downstream consumers via task_creator::schedule() (gpu_pipeline_executor and
   272	  // duckdb_scan_executor both do this). Each such request holds a raw
   273	  // sirius_physical_operator* owned by the engine, which is destroyed the moment
   274	  // execute() returns. If the task_creator is live (or restarted) while those
   275	  // requests are still in flight, its manager_loop dereferences a freed operator
   276	  // in get_operator_for_next_task() — a use-after-free that crashes intermittently
   277	  // under multi-partition sort with many in-flight pipeline tasks.
   278	  //
   279	  // So: stop the task_creator FIRST and keep its queue interrupted across the
   280	  // executor drains. With the queue interrupted, schedule() pushes from
   281	  // completion callbacks return false and the requests (and their dangling
   282	  // operator pointers) are dropped instead of processed. Only AFTER every
   283	  // executor has quiesced do we drain the creation queue and restart the
   284	  // creator for the next query.
   285	  if (_task_creator) { _task_creator->stop_thread_pool(); }
   286	
   287	  // Drain the top-level task queue so management_eventloop doesn't dispatch
   288	  // stale tasks from the failed query.
   289	  _task_queue.drain();
   290	
   291	  // Interrupt each GPU executor's manager loop, wait for in-flight thread-pool
   292	  // tasks to finish, then restart the manager for the next query.
   293	  for (auto& [device_id, gpu_exec] : _gpu_executors) {
   294	    gpu_exec->drain_and_wait();
   295	    auto const m = gpu_exec->get_metrics();
   296	    SIRIUS_LOG_INFO(
   297	      "task_scheduler: GPU:{} executor metrics (cumulative): tasks_executed={} "
   298	      "oom_reschedules={} futile_aborts={}",
   299	      device_id,
   300	      m.tasks_executed,
   301	      m.oom_reschedules,
   302	      m.futile_aborts);
   303	  }
   304	
   305	  // Now that no executor can generate further task_creation_requests, discard
   306	  // any that accumulated (and release the shared_ptr<data_batch> references they
   307	  // hold, which would otherwise survive clear_all_repositories at QueryEnd and
   308	  // show up as inter-iteration "memory leak" warnings). drain_pending_tasks()
   309	  // reactivates the queue when done.
   310	  if (_task_creator) { _task_creator->drain_pending_tasks(); }
   311	
   312	  // Belt-and-suspenders: the executor restarts above emit device_ready signals,
   313	  // and the management loop may have dispatched a leftover task into an executor
   314	  // queue between the two drains. Clear the top-level queue once more so the
   315	  // next query starts from empty.
   316	  _task_queue.drain();
   317	
   318	  if (_task_creator) { _task_creator->start_thread_pool(); }
   319	  SIRIUS_LOG_INFO("task_scheduler: DONE draining after error");
   320	}

